-- Add standalone "Cohort Suggestions" subject (term 0 = Common, shown outside Term 1/Term 2).
-- Id-based + idempotent; pure-ASCII JSON literal (clipboard-safe).
update public.catalog set data = jsonb_set(
  data, '{subjects}',
  (select coalesce(jsonb_agg(s), '[]'::jsonb) from jsonb_array_elements(data->'subjects') s where s->>'id' <> 'sub_cohort')
  || $j$[{"id":"sub_cohort","name":"Cohort Suggestions","code":"Common","color":"#6b7280","icon":"","term":0,"lus":[{"id":"cohort_lu01","title":"Suggested by Participants","url":"","selfStudy":false,"outcomes":[],"mandatory":[],"recommended":[{"id":"cohort_r01","name":"A Sixth of Humanity: Independent India's Development Odyssey","desc":"Kapur and Subramanian - suggested by Ayush","url":"https://www.amazon.in/Sixth-Humanity-Independent-Development-Odyssey/dp/9369891099"},{"id":"cohort_r02","name":"Accelerating India's Development: A State-Led Roadmap for Effective Governance","desc":"Karthik Muralidharan - suggested by Ayush","url":"https://www.amazon.in/Accelerating-Indias-Development-State-Led-Governance/dp/067009594X"},{"id":"cohort_r03","name":"Randomistas vs Contestistas","desc":"SSIR excerpt - suggested by Abhinav","url":"https://ssir.org/books/excerpts/entry/randomistas_vs_contestistas"},{"id":"cohort_r04","name":"Towards Win-Win: Commercial Dispute Resolution in India","desc":"Rao, Sohail, Seetharaman and Pandey - suggested by Valay Singh","url":"https://www.povertyactionlab.org/sites/default/files/research-paper/Towards%20win-win%20Evidence%20from%20commercial%20courts.pdf"},{"id":"cohort_r05","name":"Whole Numbers and Half Truths","desc":"Rukmini S - suggested by Lasya","url":"https://www.amazon.in/Whole-Numbers-Half-Truths-Cannot/dp/9391234674"},{"id":"cohort_r06","name":"The Rs 3,000-crore MLA who became a beggar for a day","desc":"News (Free Press Journal) - suggested by Ram","url":"https://www.freepressjournal.in/mumbai/mumbai-bjp-mla-parag-shah-with-3383-crore-assets-turns-beggar-for-one-day-in-ghatkopar-looks-unrecognisable-know-why-he-did-it-mumbai-news"}]}]}]$j$::jsonb
) where id = 1;
